<script type="module">
import * as THREE from 'three';

const W = 240, H = 242;
const renderer = new THREE.WebGLRenderer({ preserveDrawingBuffer: true, antialias: true });
renderer.setPixelRatio(1);
renderer.setSize(W, H, false);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x918d72);

const camera = new THREE.PerspectiveCamera(30.5, W / H, 0.1, 80);
camera.position.set(0, 6.8, 10.8);
camera.lookAt(0, 2.55, 0.15);

const unitBox = new THREE.BoxGeometry(1, 1, 1);
const unitSphere = new THREE.SphereGeometry(1, 32, 24);
const smallSphere = new THREE.SphereGeometry(1, 18, 12);
const yAxis = new THREE.Vector3(0, 1, 0);

function standard(color, roughness = 0.65) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness: 0 });
}

function addMesh(parent, name, geometry, material, cast = true, receive = true) {
  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = name;
  mesh.castShadow = cast;
  mesh.receiveShadow = receive;
  parent.add(mesh);
  return mesh;
}

function addBox(parent, name, sx, sy, sz, x, y, z, material, cast = true, receive = true) {
  const mesh = addMesh(parent, name, unitBox, material, cast, receive);
  mesh.scale.set(sx, sy, sz);
  mesh.position.set(x, y, z);
  return mesh;
}

function addSphere(parent, name, x, y, z, sx, sy, sz, material, low = false) {
  const mesh = addMesh(parent, name, low ? smallSphere : unitSphere, material);
  mesh.position.set(x, y, z);
  mesh.scale.set(sx, sy, sz);
  return mesh;
}

let seed = 73129;
function random() {
  seed = (seed * 1664525 + 1013904223) >>> 0;
  return seed / 4294967296;
}

function makeWoodTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 64;
  const g = canvas.getContext('2d');
  g.fillStyle = '#aa713b';
  g.fillRect(0, 0, 64, 64);
  for (let i = 0; i < 46; i++) {
    const y = random() * 64;
    g.strokeStyle = `rgba(${75 + random() * 35},${42 + random() * 25},${20 + random() * 15},${0.05 + random() * 0.12})`;
    g.lineWidth = 0.35 + random() * 1.1;
    g.beginPath();
    g.moveTo(0, y);
    for (let x = 0; x <= 64; x += 8) {
      g.lineTo(x, y + Math.sin(x * 0.12 + i) * (0.5 + random()));
    }
    g.stroke();
  }
  for (let i = 0; i < 5; i++) {
    g.strokeStyle = 'rgba(74,42,20,0.10)';
    g.beginPath();
    g.ellipse(random() * 64, random() * 64, 5 + random() * 8, 1 + random() * 2, 0, 0, Math.PI * 2);
    g.stroke();
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(3, 2);
  return texture;
}

function makeBoardTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 64;
  const g = canvas.getContext('2d');
  g.fillStyle = '#3d5754';
  g.fillRect(0, 0, 64, 64);
  for (let i = 0; i < 20; i++) {
    g.strokeStyle = `rgba(190,200,177,${0.012 + random() * 0.025})`;
    g.lineWidth = 1 + random() * 3;
    g.beginPath();
    const y = random() * 64;
    g.moveTo(random() * 20, y);
    g.bezierCurveTo(20, y - 2, 43, y + 3, 52 + random() * 12, y);
    g.stroke();
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function makeShadowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 64;
  const g = canvas.getContext('2d');
  const gradient = g.createRadialGradient(32, 32, 2, 32, 32, 31);
  gradient.addColorStop(0, 'rgba(45,31,15,0.42)');
  gradient.addColorStop(0.45, 'rgba(45,31,15,0.20)');
  gradient.addColorStop(1, 'rgba(45,31,15,0)');
  g.fillStyle = gradient;
  g.fillRect(0, 0, 64, 64);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

const woodTexture = makeWoodTexture();
const boardTexture = makeBoardTexture();
const shadowTexture = makeShadowTexture();

const M = {
  wall: standard(0x99957a, 0.95),
  floor: standard(0x75634b, 0.95),
  wood: new THREE.MeshStandardMaterial({ map: woodTexture, roughness: 0.72 }),
  darkWood: standard(0x76502f, 0.8),
  frame: standard(0x82734d, 0.82),
  frameLight: standard(0xa28b5b, 0.8),
  board: new THREE.MeshBasicMaterial({ map: boardTexture }),
  leftSkin: standard(0xd8cf52, 0.56),
  rightSkin: standard(0xe5b733, 0.54),
  leftBelly: standard(0xe6dfa0, 0.72),
  rightBelly: standard(0xead58e, 0.7),
  leftHand: standard(0xcfc650, 0.6),
  rightHand: standard(0x9b8948, 0.64),
  socket: standard(0x7d8169, 0.48),
  eye: new THREE.MeshPhysicalMaterial({
    color: 0x151a16,
    roughness: 0.14,
    metalness: 0,
    clearcoat: 1,
    clearcoatRoughness: 0.1
  }),
  highlight: new THREE.MeshBasicMaterial({ color: 0xfffdf0, toneMapped: false }),
  mouth: standard(0x4c4c2d, 0.7),
  paper: standard(0xf0eddc, 0.92),
  paperEdge: standard(0xd5d0b9, 0.95),
  pencil: standard(0x5a4930, 0.6),
  pencilWood: standard(0xd6b77b, 0.72),
  graphite: standard(0x292b28, 0.5),
  pen: standard(0x393c38, 0.4)
};
M.board.toneMapped = false;

const ambient = new THREE.AmbientLight(0xfff7e5, 0.42);
scene.add(ambient);

const hemi = new THREE.HemisphereLight(0xfff7df, 0x77644d, 1.35);
scene.add(hemi);

const key = new THREE.DirectionalLight(0xffedc9, 3.0);
key.position.set(-3.8, 8.5, 6.5);
key.target.position.set(0, 2, 0);
