const room = new THREE.Group();
room.name = 'classroom';
scene.add(room);

const wall = addMesh(room, 'rear-wall', new THREE.PlaneGeometry(18, 10), M.wall, false, true);
wall.position.set(0, 3.8, -3.42);

const floor = addMesh(room, 'floor', new THREE.PlaneGeometry(24, 24), M.floor, false, true);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -0.08;

addBox(room, 'baseboard', 18, 0.18, 0.1, 0, 0.12, -3.32, M.frame, false, true);
addBox(room, 'chalkboard', 10.5, 2.62, 0.08, 0, 4.25, -3.25, M.board, false, false);
addBox(room, 'board-frame-left', 0.13, 2.82, 0.13, -5.31, 4.25, -3.19, M.frame, false, true);
addBox(room, 'board-frame-right', 0.13, 2.82, 0.13, 5.31, 4.25, -3.19, M.frame, false, true);
addBox(room, 'board-frame-top', 10.75, 0.14, 0.13, 0, 5.62, -3.19, M.frame, false, true);
addBox(room, 'board-frame-bottom', 10.75, 0.16, 0.16, 0, 2.88, -3.17, M.frameLight, false, true);
addBox(room, 'chalk-tray', 10.7, 0.09, 0.34, 0, 2.79, -3.02, M.frame, false, true);
addBox(room, 'chalk-piece', 0.23, 0.045, 0.055, -2.8, 2.86, -2.89, M.paperEdge, false, true);

function makeBackgroundDesk(x, z, width) {
  const group = new THREE.Group();
  group.name = 'background-desk';
  group.position.set(x, 0, z);
  room.add(group);
  addBox(group, 'desktop', width, 0.13, 1.0, 0, 1.24, 0, M.darkWood);
  addBox(group, 'apron', width - 0.12, 0.31, 0.09, 0, 1.02, 0.42, M.frame);
  addBox(group, 'leg-left', 0.1, 1.15, 0.1, -width * 0.38, 0.57, 0.32, M.darkWood);
  addBox(group, 'leg-right', 0.1, 1.15, 0.1, width * 0.38, 0.57, 0.32, M.darkWood);
}
makeBackgroundDesk(-3.05, -1.5, 1.75);
makeBackgroundDesk(3.0, -1.65, 1.8);

function makeChair(x, z, rotation) {
  const chair = new THREE.Group();
  chair.name = 'wooden-chair';
  chair.position.set(x, 0, z);
  chair.rotation.y = rotation;
  room.add(chair);
  addBox(chair, 'chair-back-top', 1.25, 0.14, 0.13, 0, 1.75, 0, M.darkWood);
  addBox(chair, 'chair-back-left', 0.12, 1.1, 0.12, -0.52, 1.22, 0, M.frame);
  addBox(chair, 'chair-back-right', 0.12, 1.1, 0.12, 0.52, 1.22, 0, M.frame);
  addBox(chair, 'chair-back-slat', 0.92, 0.36, 0.08, 0, 1.43, 0, M.frame);
  addBox(chair, 'chair-seat', 1.25, 0.12, 0.95, 0, 0.73, 0.35, M.darkWood);
}
makeChair(-2.65, -1.15, 0.08);
makeChair(2.75, -1.4, -0.1);

const desk = new THREE.Group();
desk.name = 'foreground-desk';
scene.add(desk);
addBox(desk, 'desktop', 8.2, 0.18, 3.1, 0, 0.62, 1.55, M.wood, true, true);
addBox(desk, 'front-apron', 8.0, 0.38, 0.12, 0, 0.37, 3.02, M.darkWood);
addBox(desk, 'left-leg', 0.18, 0.68, 0.18, -3.35, 0.25, 2.45, M.darkWood);
addBox(desk, 'right-leg', 0.18, 0.68, 0.18, 3.35, 0.25, 2.45, M.darkWood);

const contactMaterial = new THREE.MeshBasicMaterial({
  map: shadowTexture,
  transparent: true,
  depthWrite: false,
  toneMapped: false
});
for (const [x, z, sx, sz] of [[-1.25, 0.45, 2.8, 1.8], [1.35, 0.15, 2.7, 1.7]]) {
  const shadow = addMesh(scene, 'soft-contact-shadow', new THREE.PlaneGeometry(sx, sz), contactMaterial, false, false);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(x, 0.716, z);
