function radiusAt(samples, y) {
  if (y <= samples[0].y) return Math.max(0, samples[0].x);
  for (let i = 1; i < samples.length; i++) {
    if (samples[i].y >= y) {
      const a = samples[i - 1], b = samples[i];
      const f = (y - a.y) / Math.max(0.00001, b.y - a.y);
      return Math.max(0, THREE.MathUtils.lerp(a.x, b.x, f));
    }
  }
  return 0;
}

function makeOrganicBody(parent, name, controls, zScale, material) {
  const points = controls.map(([y, r]) => new THREE.Vector3(r, y, 0));
  const curve = new THREE.CatmullRomCurve3(points, false, 'centripetal');
  const samples = curve.getPoints(128);
  const profile = samples.map(p => new THREE.Vector2(Math.max(0, p.x), p.y));
  const geometry = new THREE.LatheGeometry(profile, 64);
  const body = addMesh(parent, name, geometry, material);
  body.scale.z = zScale;
  return { body, samples, zScale };
}

function makeBelly(parent, name, bodyData, y0, y1, maxAngle, material) {
  const rows = 32, cols = 26;
  const positions = [], indices = [];
  const { samples, zScale } = bodyData;
  for (let v = 0; v <= rows; v++) {
    const fv = v / rows;
    const y = THREE.MathUtils.lerp(y0, y1, fv);
    const half = maxAngle * Math.pow(Math.max(0, Math.sin(Math.PI * fv)), 0.56);
    const radius = radiusAt(samples, y);
    for (let u = 0; u <= cols; u++) {
      const fu = u / cols;
      const angle = (fu * 2 - 1) * half;
      positions.push(
        radius * Math.sin(angle),
        y,
        (radius * Math.cos(angle) + 0.012) * zScale
      );
    }
  }
  for (let v = 0; v < rows; v++) {
    for (let u = 0; u < cols; u++) {
      const a = v * (cols + 1) + u;
      const b = (v + 1) * (cols + 1) + u;
      const c = b + 1;
      const d = a + 1;
      indices.push(a, d, b, b, d, c);
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return addMesh(parent, name, geometry, material, false, true);
}

function makeLimb(parent, name, points, r0, r1, material, steps = 32, radial = 14) {
  const group = new THREE.Group();
  group.name = name;
  parent.add(group);
  const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(...p)), false, 'centripetal');
  const frames = curve.computeFrenetFrames(steps, false);
  const positions = [], indices = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const center = curve.getPointAt(t);
    const smooth = t * t * (3 - 2 * t);
    const radius = THREE.MathUtils.lerp(r0, r1, smooth) * (1 - 0.035 * Math.sin(Math.PI * t));
    for (let j = 0; j <= radial; j++) {
      const angle = j / radial * Math.PI * 2;
      const normal = frames.normals[i];
      const binormal = frames.binormals[i];
      positions.push(
        center.x + radius * (Math.cos(angle) * normal.x + Math.sin(angle) * binormal.x),
        center.y + radius * (Math.cos(angle) * normal.y + Math.sin(angle) * binormal.y),
        center.z + radius * (Math.cos(angle) * normal.z + Math.sin(angle) * binormal.z)
      );
    }
  }
  for (let i = 0; i < steps; i++) {
    for (let j = 0; j < radial; j++) {
      const a = i * (radial + 1) + j;
      const b = (i + 1) * (radial + 1) + j;
      const c = b + 1;
      const d = a + 1;
      indices.push(a, d, b, b, d, c);
    }
  }
  const startCenter = positions.length / 3;
  const p0 = curve.getPointAt(0);
  positions.push(p0.x, p0.y, p0.z);
  const endCenter = positions.length / 3;
  const p1 = curve.getPointAt(1);
  positions.push(p1.x, p1.y, p1.z);
  for (let j = 0; j < radial; j++) {
    indices.push(startCenter, j + 1, j);
    const a = steps * (radial + 1) + j;
    indices.push(endCenter, a, a + 1);
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  addMesh(group, name + '-surface', geometry, material);
  return group;
}

function makeEye(parent, name, x, y, z, size, gazeX, gazeY) {
  const eye = new THREE.Group();
  eye.name = name;
  eye.position.set(x, y, z);
  eye.rotation.y = x * 0.28;
  eye.scale.setScalar(size);
  parent.add(eye);

  addSphere(eye, name + '-socket', 0, 0, 0, 0.255, 0.325, 0.125, M.socket);

  const eyeball = new THREE.Group();
  eyeball.name = name + '-eyeball';
  eyeball.position.set(gazeX, gazeY, 0.083);
  eye.add(eyeball);
  addSphere(eyeball, name + '-dark-eye', 0, 0, 0, 0.19, 0.26, 0.108, M.eye);
  addSphere(eyeball, name + '-highlight-large', -0.056, 0.076, 0.104, 0.043, 0.056, 0.018, M.highlight, true);
  addSphere(eyeball, name + '-highlight-small', 0.047, -0.047, 0.105, 0.017, 0.022, 0.009, M.highlight, true);
  return eye;
}

function makeMouth(parent, name, x, y, z, width, smirk = false) {
  const group = new THREE.Group();
  group.name = name;
  group.position.set(x, y, z);
  parent.add(group);
  const curve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(-width, smirk ? -0.005 : 0.018, 0),
    new THREE.Vector3(-width * 0.42, -0.035, 0.012),
    new THREE.Vector3(width * 0.35, -0.034, 0.012),
    new THREE.Vector3(width, smirk ? 0.042 : 0.018, 0)
  ]);
  addMesh(group, name + '-smile', new THREE.TubeGeometry(curve, 18, 0.018, 7, false), M.mouth, false, false);
  return group;
}

function makeHand(parent, name, position, material, kind) {
  const hand = new THREE.Group();
  hand.name = name;
  hand.position.set(...position);
  parent.add(hand);

  if (kind === 'writing') {
    hand.rotation.z = -0.28;
    addSphere(hand, name + '-palm', 0, 0, 0, 0.215, 0.165, 0.18, material);
    for (let i = 0; i < 3; i++) {
      const z = -0.09 + i * 0.085;
      makeLimb(hand, name + '-finger-' + i, [
        [-0.09, 0.07, z],
        [0.015, 0.015, z + 0.04],
        [0.09, -0.075, z + 0.025]
      ], 0.052, 0.038, material, 12, 9);
      addSphere(hand, name + '-fingertip-' + i, 0.09, -0.075, z + 0.025, 0.04, 0.04, 0.04, material, true);
    }
  } else if (kind === 'comfort') {
    hand.rotation.z = 0.18;
    addSphere(hand, name + '-palm', 0, 0, 0, 0.285, 0.19, 0.205, material);
    for (let i = 0; i < 3; i++) {
      const z = -0.12 + i * 0.115;
      makeLimb(hand, name + '-finger-' + i, [
        [-0.08, -0.015, z],
        [-0.21, -0.095, z + 0.025],
        [-0.29, -0.21 + i * 0.025, z + 0.01]
      ], 0.061, 0.041, material, 14, 9);
      addSphere(hand, name + '-fingertip-' + i, -0.29, -0.21 + i * 0.025, z + 0.01, 0.043, 0.043, 0.043, material, true);
    }
  } else {
    addSphere(hand, name + '-palm', 0, 0, 0, 0.23, 0.17, 0.18, material);
    for (let i = 0; i < 3; i++) {
      makeLimb(hand, name + '-finger-' + i, [
        [-0.09, -0.03, -0.09 + i * 0.09],
        [-0.18, -0.11, -0.09 + i * 0.09],
        [-0.2, -0.19, -0.08 + i * 0.09]
      ], 0.048, 0.034, material, 10, 8);
    }
  }
  return hand;
}

function buildLeftCharacter() {
  const root = new THREE.Group();
  root.name = 'character-left';
  root.position.set(-1.35, 0.65, 0.25);
  root.rotation.set(0, 0.08, -0.07);
  scene.add(root);

  const bodyGroup = new THREE.Group();
  bodyGroup.name = 'left-body';
  root.add(bodyGroup);
  const bodyData = makeOrganicBody(bodyGroup, 'left-body-volume', [
    [-0.25, 0], [-0.19, 0.52], [-0.02, 0.82], [0.30, 0.99],
    [0.85, 1.08], [1.25, 1.06], [1.65, 0.96], [1.98, 0.82],
    [2.28, 0.80], [2.62, 0.87], [3.02, 0.93], [3.36, 0.88],
    [3.65, 0.70], [3.88, 0.42], [4.05, 0]
  ], 0.82, M.leftSkin);
  makeBelly(bodyGroup, 'left-cream-belly', bodyData, -0.10, 1.45, 0.79, M.leftBelly);

  const head = new THREE.Group();
  head.name = 'left-head';
  head.position.x = 0.15;
  root.add(head);
  makeEye(head, 'left-eye-left', -0.45, 3.14, 0.70, 1.03, 0.018, -0.025);
  makeEye(head, 'left-eye-right', 0.55, 3.28, 0.70, 0.91, 0.018, -0.035);
  makeMouth(head, 'left-mouth', 0.02, 2.55, 0.735, 0.14);

  const writingArm = new THREE.Group();
  writingArm.name = 'left-writing-arm';
  root.add(writingArm);
  makeLimb(writingArm, 'left-writing-arm-volume', [
    [-0.82, 2.05, 0.05],
    [-1.02, 1.15, 0.50],
    [-0.88, 0.48, 0.90]
  ], 0.225, 0.15, M.leftSkin);
  makeHand(writingArm, 'left-writing-hand', [-0.88, 0.48, 0.90], M.leftHand, 'writing');

  const restingArm = new THREE.Group();
  restingArm.name = 'left-resting-arm';
  root.add(restingArm);
  makeLimb(restingArm, 'left-resting-arm-volume', [
    [0.78, 1.95, 0.02],
    [0.95, 1.20, 0.48],
    [0.82, 0.82, 0.90]
  ], 0.22, 0.15, M.leftSkin);
  makeHand(restingArm, 'left-resting-hand', [0.82, 0.82, 0.90], M.leftHand, 'resting');
  return root;
}

function buildRightCharacter() {
  const root = new THREE.Group();
  root.name = 'character-right';
  root.position.set(1.45, 0.85, -0.45);
  root.rotation.set(0, -0.25, 0.08);
  scene.add(root);

  const bodyGroup = new THREE.Group();
  bodyGroup.name = 'right-body';
  root.add(bodyGroup);
  const bodyData = makeOrganicBody(bodyGroup, 'right-body-volume', [
    [-0.35, 0], [-0.27, 0.58], [-0.05, 0.91], [0.35, 1.10],
    [0.85, 1.14], [1.30, 1.08], [1.75, 0.96], [2.12, 0.84],
    [2.48, 0.87], [2.90, 0.98], [3.30, 1.00], [3.62, 0.91],
    [3.92, 0.70], [4.16, 0.42], [4.35, 0]
  ], 0.84, M.rightSkin);
  makeBelly(bodyGroup, 'right-cream-belly', bodyData, -0.22, 1.35, 0.82, M.rightBelly);

  const head = new THREE.Group();
  head.name = 'right-head';
  root.add(head);
